        }
		private void ChangeApp(int nextIndex) {
            CurrentApp.OnAppChanged();
            CurrentApp.Close();
            CurrentAppIndex = nextIndex;
            CurrentApp.Open(this);
            CurrentApp.OnSizeChanged(IsLarge);
            SetNumImage((uint)(CurrentApp.AppID + 1), 2, _numImages, _numSprites, 0);
        }
		public void SetAppColor(int index) {
            _appBG.color = _bgColors[index];
            _numImages[0].color = _bgColors[index];
            _numImages[1].color = _bgColors[index];
        }
		public void SetAppBackLight() {
            SetBackLight(_isTouch);
        }
		public void SetBackLight(bool isEnable) {
            if (_isBackLight == isEnable)
                return;

            _isBackLight = isEnable;
            Color color = _appBG.color;
            if (isEnable)
                color += _lightColor;
            else
                color -= _lightColor;

            _appBG.color = color;
        }
		public void PlayPokemonVoice(global::Pml.MonsNo monsNo, int formNo = 0, global::Pml.Sex monsSex = (global::Pml.Sex)(3), global::Pml.PokePara.RareType rareType = (global::Pml.PokePara.RareType)(0)) {
            if (_voiceTimer <= 0.0f)
            {
                if (monsSex == Sex.NUM)
                {
                    uint sexVector = Pml.Personal.PersonalTableExtensions.GetParam(Pml.Personal.PersonalSystem.GetPersonalData(monsNo, (ushort)formNo), Pml.Personal.ParamID.SEX);
                    monsSex = sexVector == (uint)Pml.Personal.SexVector.UNKNOWN ? Sex.UNKNOWN : (sexVector == (uint)Pml.Personal.SexVector.ONLY_FEMALE ? Sex.FEMALE : Sex.MALE);
                }

                _voiceData = UIManager.Instance.GetPokemonVoiceData(monsNo, (ushort)formNo, monsSex, rareType, false);
                if (_voiceInstance != null)
                    _voiceInstance.Stop();

                _voiceInstance = AudioManager.Instance.PlayVoice(AudioManager.Instance.GetIdByName(_voiceData.WwiseEvent), AudioManager.Instance.GetIdByName(_voiceData.stopEventId), (instance) =>
                {
                    if (_voiceInstance == instance)
                        _voiceInstance = null;
                });
                _voiceMonsNo = monsNo;
                _voiceTimer = _voiceWait;
            }
        }
		public bool IsCursorOnDisplay() {
            // Shipped: the Y test is CursorY >= _cursorMaxY && CursorY <= _cursorMinY (the window stores the bottom edge in _cursorMaxY).
            return CursorX <= _cursorMaxX && CursorX >= _cursorMinX && CursorY >= _cursorMaxY && CursorY <= _cursorMinY;
        }
		public static void SetNumImage(ulong num, int digit, global::UnityEngine.UI.Image[] numImage, global::UnityEngine.Sprite[] numSprite, int dispIndex = 0) {
            for (int i = 0; i < digit; i++)
            {
                ulong div = (ulong)Mathf.Pow(10.0f, i);
                numImage[dispIndex + i].enabled = true;
#if !SWITCH
                // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                numImage[dispIndex + i].sprite = numSprite[global::PcPlatform.PcIntDiv.Div(global::PcPlatform.PcIntDiv.Rem(num, div * 10), div)];
#else
                numImage[dispIndex + i].sprite = numSprite[num % (div * 10) / div];
#endif
            }
        }
		public PoketchWindow() { }
		static PoketchWindow() { }
		public enum TouchState
		{
			None = 0,
			Touch = 1,
			Hold = 2,
			Release = 3,
			Push = 4,
		}
		// s40: world pixels per UI unit (PcPlatform.PcUiRoot.UnitScale; 1 at 1280x720). The cursor (CursorX / Y) and the bounds below
		// are Screen Space Overlay WORLD positions (pixels); the cursor speed, AppWidth / AppHeight (sizeDelta) and the button offsets
		// are UI units - pixels only on the 1280x720 Switch. Above 720p the cursor crawled and its bounds shrank around the centre.
		public float PcUnit { get { return PcPlatform.PcUiRoot.UnitScale(this); } }
	}
}
